package dev.sablelife.testing;
import dev.sablelife.client.*;import dev.sablelife.module.*;import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.item.*;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.component.CustomData;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.ClientTickEvent;
@EventBusSubscriber(modid="sablelife_tests",value=Dist.CLIENT)
public final class ArmorRuleClientPreview {
 private static Preview screen;private static int ticks,index;
 @SubscribeEvent public static void tick(ClientTickEvent.Post e)throws Exception{if(!Boolean.getBoolean("sablelife.armorRulePreview"))return;var mc=Minecraft.getInstance();if(screen==null){if(mc.screen==null||mc.getOverlay()!=null||mc.level!=null)return;mc.options.guiScale().set(1);mc.resizeDisplay();screen=new Preview();mc.setScreen(screen);return;}if(++ticks==20){var dir=mc.gameDirectory.toPath().resolve("screenshots");java.nio.file.Files.createDirectories(dir);try(var img=Screenshot.takeScreenshot(mc.getMainRenderTarget())){img.writeToFile(dir.resolve("armor-rules-"+index+".png"));}}if(ticks==25){ticks=0;if(++index==4){System.out.println("Armor rule loading/empty/populated GUI 1-4 passed");mc.stop();}else{mc.options.guiScale().set(index+1);mc.resizeDisplay();}}}
 private static final class Preview extends Screen {ArmorRuleScreen panel;Preview(){super(Component.empty());}@Override protected void init(){var inv=new Inventory(null);var menu=new ArmorRuleMenu(1,inv);panel=new ArmorRuleScreen(menu,inv,title);panel.init(minecraft,width,height);var config=new ArmorRules();var tag=new net.minecraft.nbt.CompoundTag();tag.putBoolean("Ready",true);tag.putBoolean("Editable",true);tag.put("Groups",config.save());var paper=new ItemStack(Items.PAPER);paper.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));menu.getSlot(0).set(paper);panel.init(minecraft,width,height);for(int i=0;i<18;i++){var r=config.add();r.edit("channel",i+1);r.edit("source",i%2);r.edit("when",i%2);r.edit("modifier",i==0?-100:i%2==0?-50:50);}tag.put("Groups",config.save());paper.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));panel.init(minecraft,width,height);}@Override public void render(GuiGraphics g,int x,int y,float p){panel.render(g,-100,-100,p);}}
}
